/* ========================================================================== */
/* Portal UX v39 - clean, compact and consistent visual system                */
/* ========================================================================== */

:root {
  --qori-canvas: #f3f7fb;
  --qori-surface: #ffffff;
  --qori-surface-soft: #f6fbff;
  --qori-line: #d8e6f2;
  --qori-line-strong: #b8d2e9;
  --qori-ink: #071832;
  --qori-muted: #53677f;
  --qori-primary: #0759d6;
  --qori-primary-dark: #052a6b;
  --qori-primary-soft: #eaf4ff;
  --qori-focus: rgba(0, 191, 229, 0.2);
  --qori-radius-control: 9px;
  --qori-radius-panel: 14px;
  --qori-sidebar: 248px;
  --qori-sidebar-collapsed: 68px;
  --qori-topbar: 64px;
  --qori-shadow: 0 3px 12px rgba(5, 42, 107, 0.045);
}

/* Qori portal visual excellence v134 - station lite proof and flat RMS workspace. */
html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-screen-shell {
  gap: 12px !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell :where(.rms-station-navigation-hub, .rms-station-primary-brief, .rms-station-command-dock, .rms-station-screen, .rms-station-clean-shell) {
  border-radius: 10px !important;
  box-shadow: none !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-primary-brief {
  grid-template-columns: 40px minmax(0,1fr) auto !important;
  padding: 10px 12px !important;
  border: 1px solid rgba(5, 42, 107, 0.14) !important;
  background: #f7fbff !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-brief-metrics {
  display: none !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-command-dock {
  position: static !important;
  grid-template-columns: minmax(0,1fr) auto !important;
  padding: 8px 10px !important;
  border: 1px solid rgba(5, 42, 107, 0.13) !important;
  background: #ffffff !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-command-status > .material-symbols-outlined {
  width: 30px !important;
  height: 30px !important;
  border-radius: 8px !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-command-status small {
  display: none !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-command-actions {
  display: flex !important;
  flex-wrap: wrap !important;
  justify-content: flex-end !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-command-actions > button {
  min-height: 36px !important;
  padding: 7px 11px !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-screen {
  border: 1px solid rgba(205, 224, 244, 0.9) !important;
  background: #ffffff !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-screen-head {
  min-height: 48px !important;
  grid-template-columns: minmax(0,1fr) auto auto !important;
  gap: 10px !important;
  padding: 9px 12px !important;
  border-bottom: 1px solid rgba(205, 224, 244, 0.78) !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-build-badge {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-height: 28px !important;
  padding: 5px 9px !important;
  border: 1px solid rgba(7, 206, 251, 0.38) !important;
  border-radius: 999px !important;
  background: #e8f7ff !important;
  color: #052a6b !important;
  font-size: 0.68rem !important;
  font-weight: 900 !important;
  white-space: nowrap !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-list-head {
  padding: 10px 12px !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-lead-toolbar {
  grid-template-columns: minmax(260px,1fr) auto !important;
  padding: 8px !important;
  border-width: 0 0 1px !important;
  border-radius: 0 !important;
  background: #f7fbff !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-output-lane {
  display: none !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-clean-list {
  gap: 0 !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-lead-row {
  min-height: 62px !important;
  grid-template-columns: 38px minmax(180px,1fr) minmax(180px,0.9fr) minmax(120px,0.5fr) minmax(120px,0.55fr) auto !important;
  gap: 10px !important;
  padding: 8px 12px !important;
  border-width: 0 0 1px !important;
  border-color: rgba(205, 224, 244, 0.78) !important;
  border-radius: 0 !important;
  background: #ffffff !important;
  box-shadow: none !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-lead-row:hover,
html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-lead-row.is-selected {
  transform: none !important;
  background: #f7fbff !important;
  box-shadow: inset 3px 0 0 #07cefb !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-inline-action {
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
}

html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-show-more {
  width: calc(100% - 24px) !important;
  margin: 10px 12px 12px !important;
}

@media (max-width: 980px) {
  html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-command-dock,
  html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-screen-head,
  html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-lead-toolbar,
  html body:not(#qoriV134A#qoriV134B#qoriV134C)[data-current-view="rms-machine"] .portal-shell .rms-station-lead-row {
    grid-template-columns: 1fr !important;
  }
}

/* Qori portal visual excellence v131: Stitch-inspired forms, Qori brand colors. */
html body {
  --qori-blue-deep: #012268;
  --qori-blue-corp: #0341b3;
  --qori-blue-digital: #0152d7;
  --qori-blue-bright: #0480fa;
  --qori-cyan: #07cefb;
  --qori-ice: #e8f3fb;
  --qori-white: #ffffff;
  --qori-text: #0b1e3d;
  --qori-muted: #54708f;
  --qori-line: #cde0f4;
  --qori-canvas: #f4f9fe;
  --qori-surface: #ffffff;
  --qori-surface-soft: #f7fbff;
  --qori-line-strong: #b8d2e9;
  --qori-ink: #0b1e3d;
  --qori-primary: #0341b3;
  --qori-primary-dark: #012268;
  --qori-primary-soft: #e8f3fb;
  --qori-cyan-soft: #e8fbff;
  --qori-radius-control: 14px;
  --qori-radius-panel: 20px;
  --qori-sidebar: 208px;
  --qori-topbar: 58px;
  --qori-shadow: 0 16px 42px rgba(1, 34, 104, 0.075);
  --qori-shadow-soft: 0 8px 24px rgba(1, 34, 104, 0.055);
  --qori-gradient-main: linear-gradient(135deg, #012268 0%, #0341b3 42%, #0480fa 75%, #07cefb 100%);
  --qori-gradient-sober: linear-gradient(180deg, #012268 0%, #0152d7 100%);
  font-family: "Manrope", "Inter", "Segoe UI", system-ui, sans-serif !important;
  letter-spacing: 0 !important;
}

html body:not(#qoriV131A#qoriV131B) {
  background:
    linear-gradient(135deg, rgba(232, 243, 251, 0.92) 0%, rgba(255, 255, 255, 0.98) 44%, rgba(247, 251, 255, 0.96) 100%) !important;
