/* Estacion 08 · Riesgos de fuga. Alcance exclusivo: control_anti_fuga. */
#rmsStationWorkspace[data-station-theme="control"] {
  --rms-control-ink: #17364c;
  --rms-control-muted: #607487;
  --rms-control-line: #d7e1e8;
  --rms-control-surface: #ffffff;
  --rms-control-canvas: #f5f8fa;
  --rms-control-amber: #9a5718;
  --rms-control-amber-soft: #fff4df;
  --rms-control-coral: #b64b36;
  --rms-control-coral-soft: #fff0eb;
  --rms-control-focus: #176f9f;
}

#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station {
  gap: 16px;
  padding: 20px;
  border: 1px solid var(--rms-control-line);
  border-top: 4px solid #d89037;
  border-radius: 18px;
  background: linear-gradient(135deg, #fffdf9 0%, var(--rms-control-canvas) 54%, #f8fbfc 100%);
  color: var(--rms-control-ink);
  box-shadow: 0 16px 36px rgba(24, 53, 72, .08);
}

#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station-head {
  align-items: center;
  padding: 0 0 16px;
  border-bottom-color: #d9e2e7;
}

#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station-title {
  min-width: 0;
}

#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station-title .mono-label {
  color: var(--rms-control-amber) !important;
  font-weight: 800;
}

#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station-title h3 {
  color: var(--rms-control-ink) !important;
}

#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station-title p {
  max-width: 66ch;
  margin-top: 7px;
  padding-left: 12px;
  border-left: 3px solid #d89037;
  color: #415e72 !important;
  font-weight: 650;
  line-height: 1.48;
}

#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station-media {
  border-color: rgba(182, 75, 54, .24) !important;
  background: radial-gradient(circle at 72% 22%, #fff5df 0 18%, transparent 19%), #fffaf2 !important;
}

#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station-symbol {
  color: #934c16 !important;
}

#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station-actions,
#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station-tools {
  min-width: 0;
}

/* Barra de mando: consulta de estado separada de la operacion por caso. */
#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station-tools {
  align-items: stretch;
  gap: 10px;
  padding: 10px;
  border: 1px solid #d5e0e7;
  border-radius: 14px;
  background: rgba(255, 255, 255, .78);
  box-shadow: 0 5px 14px rgba(25, 54, 74, .04);
}

#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station-tools label {
  min-width: min(320px, 100%);
  border-color: #bdced9 !important;
  background: #fff !important;
}

#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station-tools > span,
#rmsStationWorkspace[data-station-theme="control"] .rms-lean-station-tools > small {
  align-self: center;
  padding: 7px 10px;
  border: 1px solid #ecd6af;
  border-radius: 999px;
