/* Portal layout safety contract: shared final layer, no behavior changes. */
:root {
  --portal-content-max: 1520px;
  --portal-gutter: clamp(16px, 2.2vw, 32px);
  --portal-control-height: 42px;
  --portal-line: rgba(20, 55, 90, .16);
  --portal-popover: 1040;
  --portal-modal: 1100;
  --portal-toast: 1200;
}

html, body { max-width: 100%; }
html body .portal-shell,
html body .portal-shell *,
html body > .modal-shell,
html body > .modal-shell * { box-sizing: border-box; }

/* Safe flex/grid children prevent long names, URLs and action labels from forcing a page width. */
html body .portal-shell :is(.app-main, .content-shell, .view-section, .view-head, .campaign-head, .table-card-head, .surface-card, .data-table-card, .chart-card, .modal-card, .modal-head, .modal-form, .modal-actions, .lead-detail-card, .rms-commercial-work-console) { min-width: 0; }
html body .portal-shell :is(.view-head, .campaign-head, .table-card-head, .modal-head, .modal-actions, .head-actions, .view-head-actions, .rms-station-row-actions, .rms-commercial-action-row) > * { min-width: 0; }
html body .portal-shell :is(img, svg, video, canvas) { max-width: 100%; }
html body .portal-shell .app-shell,
html body .portal-shell .app-main { min-width: 0; max-width: 100%; }
html body .portal-shell .content-shell { width: min(100%, var(--portal-content-max)); margin-inline: auto; padding-inline: var(--portal-gutter); }
html body .portal-shell .view-section.active { min-width: 0; }

html body .portal-shell :is(.view-head, .campaign-head, .table-card-head, .dashboard-builder-head, .lead-directory-head, .contact-center-head) { align-items: flex-start; gap: 14px; }
html body .portal-shell :is(.view-head-actions, .campaign-head .head-actions, .lead-export-actions, .topbar-actions, .modal-actions, .table-actions, .rms-station-row-actions, .rms-commercial-action-row) { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
html body .portal-shell :is(button, .solid-button, .ghost-button, .request-button, .nav-link-button, .link-button) { min-height: var(--portal-control-height); max-width: 100%; }
html body .portal-shell :is(button, .solid-button, .ghost-button, .request-button, .nav-link-button, .link-button) > span:last-child { min-width: 0; }

/* Tables retain readable column widths and expose an intentional horizontal scroll surface. */
html body .portal-shell :is(.table-wrap, .data-table-scroll, .table-responsive) { display: block; max-width: 100%; overflow-x: auto; overflow-y: visible; overscroll-behavior-inline: contain; scrollbar-gutter: stable; -webkit-overflow-scrolling: touch; }
html body .portal-shell :is(.table-wrap, .data-table-scroll, .table-responsive) > table { min-width: 720px; width: max-content; }
html body .portal-shell table :is(th, td) { min-width: 110px; vertical-align: top; white-space: normal; overflow-wrap: normal; word-break: normal; }
html body .portal-shell table :is(th:last-child, td:last-child) { min-width: 150px; }
html body .portal-shell :is(.table-secondary, .table-muted, td small, td .muted) { overflow-wrap: anywhere; }

html body .portal-shell :is(.form-grid, .modal-form, .sales-create-form, .sales-entry-modal-body, .rms-sale-form-grid, .rms-commercial-grid, .lead-form-grid) { grid-template-columns: repeat(auto-fit, minmax(min(100%, 220px), 1fr)); min-width: 0; }
html body .portal-shell :is(label, .form-field) { min-width: 0; }
html body .portal-shell :is(input, select, textarea) { width: 100%; min-width: 0; max-width: 100%; min-height: var(--portal-control-height); }
html body .portal-shell textarea { resize: vertical; }
html body .portal-shell :is(.error-line, .form-message, .field-error, .validation-message) { position: static; overflow-wrap: anywhere; }

/* One predictable overlay scale. Body-mounted selectors cover runtime modals. */
html body .portal-shell :is(.dropdown, .select-menu, .autocomplete-menu, .tooltip, .popover) { z-index: var(--portal-popover); max-width: min(420px, calc(100vw - 24px)); }
html body :is(.modal-shell, .modal-overlay, [role="dialog"]) { z-index: var(--portal-modal); }
html body :is(.toast-container, .toast-stack, .feedback-stack, .notification-stack) { z-index: var(--portal-toast); }
html body :is(.modal-shell:not(.hidden), .modal-overlay:not(.hidden)) { padding: max(12px, env(safe-area-inset-top)) max(12px, env(safe-area-inset-right)) max(12px, env(safe-area-inset-bottom)) max(12px, env(safe-area-inset-left)); }
html body :is(.modal-shell .modal-card, .modal-overlay .modal-card, #salesEntryModalOverlay .sales-entry-modal-card, #salesDetailModal .sales-detail-card, #rmsNegotiationModal .rms-negotiation-card) { width: min(960px, 100%); max-width: calc(100vw - 24px); max-height: calc(100dvh - 24px); min-width: 0; overflow: hidden; }
