html body[data-current-view="rms-machine"] .portal-shell :is(.rms-station-journey-nav, .rms-machine-stage-rail, .rms-stage-rail, .rms-station-clean-list) { max-width: 100%; overflow-x: auto; overscroll-behavior-inline: contain; scrollbar-gutter: stable; }
