/* Validador: las etapas de caja se leen como una sola ruta operativa. */
body[data-current-view="validator"] .portal-shell .validator-operator-hero {
  border-color: rgba(0, 211, 235, .38) !important;
  background:
    radial-gradient(circle at 81% 12%, rgba(0, 213, 236, .34), transparent 25%),
    linear-gradient(128deg, #06388e 0%, #075ccd 50%, #08466e 100%) !important;
}

body[data-current-view="validator"] .portal-shell .validator-operator-flow {
  gap: 10px !important;
  align-items: stretch;
}

body[data-current-view="validator"] .portal-shell .validator-operator-step {
  position: relative;
  grid-template-columns: 36px minmax(0, 1fr) !important;
  grid-template-rows: auto auto;
  column-gap: 9px !important;
  row-gap: 2px !important;
  align-content: center;
  min-height: 78px;
  padding: 13px !important;
  border-color: rgba(255, 255, 255, .23) !important;
  border-radius: 17px !important;
  background: linear-gradient(145deg, rgba(255,255,255,.19), rgba(255,255,255,.08)) !important;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.14), 0 9px 20px rgba(0, 28, 88, .13);
}

body[data-current-view="validator"] .portal-shell .validator-operator-step span {
  grid-row: 1 / span 2;
  width: 36px !important;
  height: 36px !important;
  border-radius: 12px !important;
  background: linear-gradient(145deg, #fff, #dffaff) !important;
  box-shadow: 0 5px 12px rgba(0, 17, 76, .18);
}

body[data-current-view="validator"] .portal-shell .validator-operator-step strong {
  align-self: end;
  letter-spacing: -.015em;
}

body[data-current-view="validator"] .portal-shell .validator-operator-step small {
  align-self: start;
  color: rgba(246, 251, 255, .86) !important;
}

body[data-current-view="validator"] .portal-shell .validator-operator-step:not(:last-child)::after {
  content: "arrow_forward";
  position: absolute;
  z-index: 2;
  top: 50%;
  right: -17px;
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  transform: translateY(-50%);
  border: 1px solid rgba(255,255,255,.32);
  border-radius: 50%;
  background: #0877c9;
  color: #fff;
  font-family: "Material Symbols Outlined";
  font-size: 14px;
  font-variation-settings: "FILL" 1, "wght" 600, "GRAD" 0, "opsz" 20;
  box-shadow: 0 4px 11px rgba(0, 22, 78, .25);
}

@media (max-width: 1050px) {
  body[data-current-view="validator"] .portal-shell .validator-operator-step:nth-child(2)::after { display: none; }
}

@media (max-width: 700px) {
  body[data-current-view="validator"] .portal-shell .validator-operator-step { min-height: 68px; }
  body[data-current-view="validator"] .portal-shell .validator-operator-step:not(:last-child)::after { top: auto; right: 20px; bottom: -16px; transform: rotate(90deg); }
  body[data-current-view="validator"] .portal-shell .validator-operator-step:nth-child(2)::after { display: grid; }
}

/* En caja se confirma primero el beneficio; el cierre comercial sigue debajo. */
