/* Qori: operaciones masivas en directorios, activaciones y comunicaciones. */
.bulk-operation-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 0 18px 14px;
  padding: 10px 12px;
  border: 1px solid rgba(103, 181, 222, .42);
  border-radius: 14px;
  background: linear-gradient(105deg, rgba(233, 248, 255, .94), rgba(247, 252, 255, .96));
  box-shadow: 0 8px 22px rgba(8, 59, 121, .08);
}

.bulk-operation-toolbar.hidden { display: none; }

.bulk-operation-summary,
.bulk-operation-actions,
.communication-history-bulk,
.communication-history-bulk > div {
  display: flex;
  align-items: center;
  gap: 8px;
}

.bulk-operation-summary .material-symbols-outlined {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 10px;
  background: #0579b9;
  color: #fff;
  font-size: 18px;
}

.bulk-operation-summary strong,
.communication-history-bulk strong { color: var(--qori-blue-deep, #012268); }
.bulk-operation-summary small { color: var(--qori-muted, #54708f); }

.bulk-table-select { width: 44px; text-align: center; }
.bulk-row-check,
.communication-history-select {
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  cursor: pointer;
}

.bulk-row-check input,
.communication-history-select input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.bulk-row-check span,
.communication-history-select span {
  width: 18px;
  height: 18px;
  border: 1.5px solid #a6c5df;
  border-radius: 6px;
  background: #fff;
  transition: .16s ease;
}

.bulk-row-check input:checked + span,
.communication-history-select input:checked + span {
  border-color: #0579b9;
  background: #0579b9;
  box-shadow: inset 0 0 0 3px #fff;
}

.bulk-row-check input:focus-visible + span,
.communication-history-select input:focus-visible + span {
  outline: 3px solid rgba(5, 121, 185, .25);
  outline-offset: 2px;
}

.gaming-activation-list-row.is-bulk-selected,
.lead-directory-row.is-bulk-selected .lead-directory-card-row,
.communication-history-item.is-bulk-selected {
  background: linear-gradient(100deg, rgba(213, 245, 255, .9), rgba(255, 255, 255, .96)) !important;
}

.lead-directory-row-check {
  align-self: center;
