/* Aviso global Qori: una señal breve de confirmación, no una tarjeta que
   interrumpa la operación. Esta capa final neutraliza las variantes antiguas
   del portal y respeta de forma estricta el atributo hidden del DOM. */
html body .content-shell > #actionFeedback[hidden],
html body .content-shell > #actionFeedback.hidden,
html body .content-shell > #actionFeedback:empty {
  display: none !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

html body .content-shell > #actionFeedback:not([hidden]):not(.hidden) {
  position: fixed !important;
  right: clamp(16px, 2.2vw, 30px) !important;
  bottom: clamp(16px, 2.4vh, 28px) !important;
  left: auto !important;
  z-index: var(--portal-toast, 1200) !important;
  width: min(356px, calc(100vw - 32px)) !important;
  margin: 0 !important;
  display: grid !important;
  grid-template-columns: 30px minmax(0, 1fr) 26px !important;
  align-items: center !important;
  gap: 10px !important;
  padding: 11px 12px !important;
  transform: translateY(0) !important;
  border: 1px solid rgba(3, 65, 179, .14) !important;
  border-radius: 14px !important;
  background: rgba(255, 255, 255, .96) !important;
  color: #163a68 !important;
  box-shadow: 0 14px 34px rgba(1, 34, 104, .13) !important;
  backdrop-filter: blur(14px) !important;
  animation: qori-feedback-toast-enter .2s var(--ease-out-premium, ease-out) both !important;
}

html body .content-shell > #actionFeedback:not([hidden]):not(.hidden)::before {
  display: grid !important;
  width: 30px !important;
  height: 30px !important;
  place-items: center !important;
  border-radius: 9px !important;
  background: #e8f3fb !important;
  color: #0341b3 !important;
  font-size: 16px !important;
}

html body .content-shell > #actionFeedback:not([hidden]):not(.hidden) strong {
  display: block !important;
  margin: 0 !important;
  color: currentColor !important;
  font-size: .79rem !important;
  font-weight: 800 !important;
  line-height: 1.2 !important;
}

html body .content-shell > #actionFeedback:not([hidden]):not(.hidden) p {
  display: -webkit-box !important;
  margin: 3px 0 0 !important;
  overflow: hidden !important;
  color: currentColor !important;
  font-size: .76rem !important;
  line-height: 1.35 !important;
  opacity: .8 !important;
  -webkit-box-orient: vertical !important;
  -webkit-line-clamp: 2 !important;
}

html body .content-shell > #actionFeedback:not([hidden]):not(.hidden) .action-feedback-dismiss {
  display: grid !important;
  width: 26px !important;
  height: 26px !important;
  place-items: center !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 8px !important;
  background: transparent !important;
  color: currentColor !important;
  cursor: pointer !important;
}

html body .content-shell > #actionFeedback:not([hidden]):not(.hidden) .action-feedback-dismiss:hover,
html body .content-shell > #actionFeedback:not([hidden]):not(.hidden) .action-feedback-dismiss:focus-visible {
  background: rgba(3, 65, 179, .08) !important;
  outline: none !important;
}

html body .content-shell > #actionFeedback.error:not([hidden]):not(.hidden) {
  border-color: rgba(169, 48, 71, .22) !important;
  background: #fff9fa !important;
  color: #8e2943 !important;
}

html body .content-shell > #actionFeedback.error:not([hidden]):not(.hidden)::before {
  background: #ffe5ea !important;
  color: #a9443d !important;
}

html body .content-shell > #actionFeedback.loading:not([hidden]):not(.hidden),
html body .content-shell > #actionFeedback.info:not([hidden]):not(.hidden) {
  border-color: rgba(7, 128, 250, .18) !important;
  background: #f8fcff !important;
  color: #07558d !important;
}

@keyframes qori-feedback-toast-enter {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 620px) {
  html body .content-shell > #actionFeedback:not([hidden]):not(.hidden) {
    right: 12px !important;
    bottom: 12px !important;
    width: calc(100vw - 24px) !important;
  }
}
